"""Формує docs/sparql_vs_cypher.md з docs/evidence/{compare,t2c_safety}.json та llm_log/eval_t2c_*.json."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
C = json.loads((ROOT / "docs/evidence/compare.json").read_text(encoding="utf-8")); S = json.loads((ROOT / "docs/evidence/t2c_safety.json").read_text(encoding="utf-8"))
E = {r: json.loads((ROOT / f"llm_log/eval_t2c_{r}.json").read_text(encoding="utf-8")) for r in ("r1", "r2")}
Q = {q["id"]: q for q in map(json.loads, (ROOT / "tests/t2c.jsonl").read_text(encoding="utf-8").splitlines())}
P = C["pairs"]; ex = C["extra"]
L = ["# Результат 5. Порівняння зі SPARQL та text-to-Cypher", "",
     "## 1. П'ять питань у SPARQL (ЛР8, pyoxigraph) і Cypher (FalkorDB)", "",
     "Дані — ті самі (RDF-граф ЛР8 і LPG, побудований з нього). Результати порівнюються як множини рядків (числа — за значенням). Довжина — символи/слова запиту без коментарів і зайвих пробілів (без рядка PREFIX); час — медіана 5 запусків після прогріву на різних рушіях, тому порівнювати рушії за часом не слід (суб-мілісекунди, малі дані).", "",
     "| № | Питання | Збіг результатів | SPARQL: довжина (симв./слів), мс | Cypher: довжина, мс |", "|---|---|---|---|---|"]
for p in P: L.append(f"| {p['id']} | {p['title']} | {'так' if p['equal'] else 'ні — пояснено нижче'} | {p['sparql_len'][0]} / {p['sparql_len'][1]}, {p['sparql_ms']} | {p['cypher_len'][0]} / {p['cypher_len'][1]}, {p['cypher_ms']} |")
L += [""]
for p in P:
    L += [f"### {p['id']}. {p['title']}", "", "```sparql", p["sparql"], "```", "", "```cypher", p["cypher"], "```", ""]
    rows = p["sparql_rows"] if p["equal"] else None
    L += [("Результат (однаковий): " + "; ".join(", ".join(r) for r in p["sparql_rows"][:8]) + ".") if p["equal"] else ("SPARQL: " + "; ".join(", ".join(r) for r in p["sparql_rows"]) + ".\n\nCypher: " + "; ".join(", ".join(r) for r in p["cypher_rows"]) + ".")]
    L += [""]
L += ["### Пояснення розбіжностей і додаткові перевірки", "",
      "- **P2.** Збіг лише тоді, коли запит Cypher також вимагає наявність анотації QD (внутрішнє з'єднання, як у SPARQL): зразок A — 22 варіанти. Якщо замінити з'єднання на `OPTIONAL MATCH` (як у запиті c03 Результату 3), для зразка A виходить **" + next(r[1] for r in ex["P2_cypher_all_variants"] if r[0] == "A") + "** варіантів: два варіанти ЛР7 (VAR-003, VAR-004) не мають анотації QD. Тобто різниця — у семантиці запиту, а не рушія.",
      "- **P5.** Cypher-версія дає на один рядок більше: `Maria` (ступінь 2, шанс 0.25) з порожнім віком; у SPARQL її немає, бо шаблон `?p dkh:hasAgeYears ?age` вимагає наявності тріпла. Cypher не відкидає рядок із `null`, а вираз `null >= 18` дає «ні». Додавши `p.ageYears IS NOT NULL`, Cypher-результат збігається зі SPARQL (перевірено: " + ("збіг" if ex["P5_cypher_with_age"] == P[4]["sparql_rows"] else "НЕ збіг") + "). Це приклад різного ставлення до відсутніх даних (шаблон проти значення null).", "",
      "## 2. Таблиця порівняння", "",
      "Оцінки «читабельність» і «зручність» — мої суб'єктивні судження за цими п'ятьма питаннями та Результатом 3; довжина й час — виміряні.", "",
      "| Критерій | SPARQL (RDF) | Cypher (LPG) |", "|---|---|---|",
      f"| Читабельність | Тріплетні шаблони з префіксами й явними змінними; шляхи читаються гірше | Шаблон «намальований» стрілками `(a)-[:R]->(b)`; для шляхів і зв'язків читається природніше |",
      f"| Довжина (сума по 5 запитах) | {sum(p['sparql_len'][0] for p in P)} симв. / {sum(p['sparql_len'][1] for p in P)} слів | {sum(p['cypher_len'][0] for p in P)} симв. / {sum(p['cypher_len'][1] for p in P)} слів |",
      f"| Час (медіана, сума по 5) | {round(sum(p['sparql_ms'] for p in P), 2)} мс (pyoxigraph) | {round(sum(p['cypher_ms'] for p in P), 2)} мс (FalkorDB) — різниця в межах накладних витрат викликів, висновку про рушії немає |",
      "| Шляхи | `+`, `*`, `^`, `\\|` — лаконічно, але без довжини й найкоротшого шляху | `*1..n`, `shortestPath`, повернення самого шляху `p`, `length(p)` |",
      "| Виведення (reasoning) | Є: у сховищі лежать матеріалізовані типи HermiT; `rdfs:subClassOf` у даних | Немає: ієрархія — вузли `SUBCLASS_OF`, виведення замінюється обходом у запиті |",
      "| Походження фактів | Окремий іменований граф або RDF-star / реіфікація (громіздко) | Властивості прямо на зв'язку (`source`, `confidence`, `validFrom`) |",
      "| Цілісність даних | SHACL (ЛР8) — декларативні форми | Унікальні обмеження й індекси; складніші перевірки — запитами |",
      "| Інтеграція | Глобальні IRI, федерація `SERVICE`, відкриті дані (Wikidata) | Ідентифікатори локальні; обмін через CSV/APOC, федерації немає |",
      "| Обмеження, виявлені в цій роботі | Немає вбудованих PageRank/Louvain; середнє округлення залежить від рушія (ROUND) | Діалекти відрізняються: у FalkorDB `shortestPath` лише в `RETURN`/`WITH` і лише спрямований, `toFloat` повертає float32; у Neo4j це інакше |", "",
      "## 3. Text-to-Cypher", "",
      "Конвеєр (`scripts/t2c.py`): **промпт зі схемою графа** (мітки з типами властивостей, типи зв'язків з кінцями — генерується з CSV) → **LLM** → **парсер** (витяг із ```cypher) → **безпека (read-only)** → **перевірка схеми** (усі мітки, типи зв'язків і властивості мають бути в схемі) → **виконання з LIMIT 100 і таймаутом 3 с** → порівняння з еталоном.", "",
      "**Read-only роль.** Два шари: (1) статичний фільтр відхиляє `CREATE, MERGE, DELETE, DETACH, SET, REMOVE, DROP, LOAD CSV, FOREACH, CALL`; (2) виконання лише через `GRAPH.RO_QUERY`, де сервер сам відхиляє запис. У Neo4j відповідник другого шару — окремий користувач із роллю `reader` (`GRANT ROLE reader TO llm_user`), у цій роботі не перевірявся, бо Neo4j тут недоступний.", "",
      "| Випадок | Статичний фільтр | Перевірка схеми |", "|---|---|---|"]
for c in S["cases"]: L.append(f"| {c['case']}: `{c['query']}` | {'пропущено' if c['static_safe'] else 'ВІДХИЛЕНО: ' + c['static_msg']} | {'—' if c['schema_ok'] is None else ('ок' if c['schema_ok'] else 'ВІДХИЛЕНО: ' + ', '.join(c['schema_msg']))} |")
L += ["", f"Другий шар: `CREATE (:Hack {{x: 1}})` через `RO_QUERY` → сервер відповів: `{S['ro_query_write_error']}`; вузлів `Hack` після спроби — {S['hack_nodes_after']}. LIMIT: до запитів без власного `LIMIT` дописується `{S['limit_appended']}`.", "",
      "### Набір питань і метрики", "",
      "`tests/t2c.jsonl`: **27 питань**, поле `tier`. Спочатку складено 16 «простих» (t01–t16); на них вийшло лише 15/16 і 16/16 правильних, тому для змістовнішого аналізу помилок **після цього** додано 11 «складних» (t17–t27: OPTIONAL MATCH з нулями, `shortestPath`, `IS NULL`, дві анотації одного варіанта, властивості зв'язків, збережені результати аналізу графа). Це рішення прийнято після перших результатів — слід враховувати при інтерпретації. Еталонні запити й відповіді склала та сама система, що й генератор. Генератори — два незалежні сліпі прогони субагентів тієї самої моделі (r1, r2; температура/seed не контролювались).", ""]
def m(run, tier=None):
    rs = [r for r in E[run] if tier is None or r["tier"] == tier]; n = len(rs)
    return [f"{sum(r['safe_ok'] for r in rs)}/{n}", f"{sum(r['schema_ok'] for r in rs)}/{n}", f"{sum(r['exec_ok'] for r in rs)}/{n}", f"{sum(r['result_ok'] for r in rs)}/{n} ({round(100*sum(r['result_ok'] for r in rs)/n)}%)"]
L += ["| Метрика | r1 всі (27) | r2 всі (27) | r1 прості (16) | r2 прості (16) | r1 складні (11) | r2 складні (11) |", "|---|---|---|---|---|---|---|"]
for i, nm in enumerate(["Пройшов фільтр безпеки", "Лише зі схеми", "Виконався без помилки", "Правильний результат"]):
    L.append(f"| {nm} | " + " | ".join(m(r, t)[i] for t in (None, "easy", "hard") for r in ("r1", "r2")) + " |")
L += ["", "**Частка коректних запитів:** 25/27 (93%) у r1 і 26/27 (96%) у r2; на 16 простих — 15/16 і 16/16; на 11 складних — 10/11 і 10/11. Вибірка мала, прогонів два, тож різниця між r1 і r2 (1 питання) — шум. Усі 27 відповідей пройшли фільтр безпеки й перевірку схеми, бо схема була в промпті.", "",
      "### Аналіз трьох помилок", "", "| Прогін | Питання | Етап | Клас | Деталь |", "|---|---|---|---|---|"]
cls = {"t14": "E1 — зайвий стовпець", "t20": "E2 — діалектна несумісність"}
for r in ("r1", "r2"):
    for x in E[r]:
        if not x["result_ok"]: L.append(f"| {r} | {x['id']} | {x['error_stage']} | {cls[x['id']]} | {x['detail'][:120]} |")
r14 = next(x for x in E["r1"] if x["id"] == "t14"); r20 = next(x for x in E["r1"] if x["id"] == "t20")
L += ["", "**E1 — зайвий стовпець (r1, t14).** Питання «Які гени мають більше п'ятнадцяти варіантів?»; модель повернула `g.symbol, cnt` (ген і кількість), еталон — лише ген. Зміст відповіді правильний (BRCA2, TP53), але метрика порівнює таблиці суворо. Це слабкість метрики, а не знань моделі; м'яка метрика (еталонні стовпці — підмножина) зарахувала б 26/27. Вихід: у промпт додати «повертай лише запитані стовпці».", "",
      "```cypher", r14["cypher"], "```", "",
      "**E2 — діалектна несумісність (r1 і r2, t20).** Питання «Скільки кроків має найкоротший шлях від Olena до Maria?». Обидва прогони написали `MATCH p = shortestPath((a)-[:HAS_PARENT*]->(b)) RETURN length(p)` — це коректний Cypher для Neo4j 5 (саме Neo4j був названий у промпті), але FalkorDB дозволяє `shortestPath` лише у `WITH`/`RETURN`, тому сервер повернув помилку: `" + r20["detail"] + "`. Отже, це помилка переносимості між рушіями, а не логіки моделі; на справжньому Neo4j запит, ймовірно, відпрацював би правильно (перевірити неможливо). Два з трьох «збоїв» — це один і той самий випадок, повторений у двох прогонах, тому незалежних класів помилок лише два. Вихід: назвати діалект у промпті (`shortestPath` лише у WITH/RETURN) — або запускати на Neo4j.", "",
      "```cypher", r20["cypher"], "```", "",
      "**Чого метрика не показує.** Запити, що дали правильний результат на цьому малому графі, можуть бути хибними на інших даних (наприклад, відсутність `DISTINCT`); їх не перевірено на варіаціях даних. Верифікація LLM-запитів тут — виконання й порівняння з еталоном (рівень V2); вимога V4 (незалежна експертна вибірка) не виконана.", ""]
(ROOT / "docs/sparql_vs_cypher.md").write_text("\n".join(L), encoding="utf-8"); print("ok")
